#!/usr/bin/env ruby
require 'json';require 'digest';require 'fileutils'
root=File.expand_path('../../..',__dir__);client=File.expand_path('../Client',root);files=Dir.glob(File.join(client,'node_modules/**/*'),File::FNM_DOTMATCH).select{|p|File.file?(p)};client_ignore=File.read(File.join(client,'.gitignore'));server_ignore=File.read(File.join(root,'.releaseignore'));scan_inputs=JSON.parse(File.read(File.join(root, 'engineering/scan-input-roots.json'))); tool_input_roots=scan_inputs.fetch('toolInputs').map { |relative| File.join(root, relative) }; script_input_roots=scan_inputs.fetch('scriptInputs').map { |relative| File.join(root, relative) }; source_tools = tool_input_roots.flat_map { |input_root| Dir.glob(File.join(input_root, '**/*')) }.uniq.select { |path| File.file?(path) }.select { |path| File.read(path, mode: 'rb').include?('node_modules') rescue false };checks={clientIgnored:client_ignore.lines.map(&:strip).include?('/node_modules/'),releaseIgnored:server_ignore.lines.map(&:strip).include?('**/node_modules/'),outsideAssets:files.all?{|p|!p.start_with?(File.join(client,'assets'))},onlyPackageManagerState:files.all?{|p|%w[.package-map.json .pnpm-workspace-state-v1.json].include?(File.basename(p))}};report={schemaVersion:1,files:files.map{|p|{path:p.delete_prefix(client+'/'),sha256:Digest::SHA256.file(p).hexdigest}},toolsMentioningNodeModules:source_tools.map{|p|p.delete_prefix(root+'/')},checks:checks,passed:checks.values.all?};out=File.join(root,'docs/generated/chyg01-node-modules.json');FileUtils.mkdir_p(File.dirname(out));File.write(out,JSON.pretty_generate(report)+"\n");abort "CHYG01 failed: #{checks}" unless report[:passed];puts 'CHYG01 PASS: node_modules excluded from source, release, assets and game inventory'
